30	    {
31	        // Development disables HTTPS redirect and is needed for the app to start correctly in tests.
32	        builder.UseEnvironment("Development");
33	
34	        builder.ConfigureAppConfiguration((_, config) =>
35	        {
36	            config.AddInMemoryCollection(new Dictionary<string, string?>
37	            {
38	                ["Authentication:Google:ClientId"] = "test-client-id",
39	                ["Authentication:Google:ClientSecret"] = "test-client-secret",
40	                ["ConnectionStrings:Kanban"] = $"Data Source={_dbPath}",
41	                ["Cors:AllowedOrigins:0"] = "http://localhost:5173",
42	                ["Seed:AdminEmail"] = AdminEmail,
43	            });
44	        });
45	
46	        builder.ConfigureServices(services =>
47	        {
48	            // Replace all authentication with the Test scheme so requests can be
49	            // authenticated by setting a header without going through Google OAuth.
50	            services.AddAuthentication(options =>
51	            {
52	                options.DefaultScheme = TestAuthenticationHandler.SchemeName;
53	                options.DefaultAuthenticateScheme = TestAuthenticationHandler.SchemeName;
54	                options.DefaultChallengeScheme = TestAuthenticationHandler.SchemeName;
55	                options.DefaultForbidScheme = TestAuthenticationHandler.SchemeName;
56	            })
57	            .AddScheme<TestAuthHandlerOptions, TestAuthenticationHandler>(
58	                TestAuthenticationHandler.SchemeName, null);
59	
60	            // Replace production rate limits with permissive values so concurrency tests
61	            // are not interfered with by the rate limiter.
62	            // MAINTENANCE: this block must enumerate every named policy defined in Program.cs.
63	            // If a new policy is added there, add it here too — a missing policy causes a
64	            // runtime error on any endpoint tagged with .RequireRateLimiting("new-policy").
65	            services.RemoveAll(typeof(IConfigureOptions<RateLimiterOptions>));
66	            services.Configure<RateLimiterOptions>(opts =>
67	            {
68	                opts.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
69	                opts.AddFixedWindowLimiter("anonymous", o =>
70	                {
71	                    o.PermitLimit = 10_000;
72	                    o.Window = TimeSpan.FromMinutes(1);
73	                });
74	                opts.AddSlidingWindowLimiter("authenticated", o =>
75	                {
76	                    o.PermitLimit = 10_000;
77	                    o.Window = TimeSpan.FromMinutes(1);
78	                    o.SegmentsPerWindow = 6;
79	                });
80	                opts.AddSlidingWindowLimiter("mutating", o =>
81	                {
82	                    o.PermitLimit = 10_000;
83	                    o.Window = TimeSpan.FromMinutes(1);
84	                    o.SegmentsPerWindow = 6;
85	                });
86	            });
87	        });
