127	    private static (string rawToken, string tokenHash) GenerateRawToken()
128	    {
129	        var bytes = System.Security.Cryptography.RandomNumberGenerator.GetBytes(32);
130	        var raw = Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
131	        var hash = Convert.ToHexString(
132	            System.Security.Cryptography.SHA256.HashData(
133	                System.Text.Encoding.UTF8.GetBytes(raw))).ToLower();
134	        return (raw, hash);
135	    }
