192	public sealed class TestAuthenticationHandler(
193	    IOptionsMonitor<TestAuthHandlerOptions> options,
194	    ILoggerFactory logger,
195	    UrlEncoder encoder)
196	    : AuthenticationHandler<TestAuthHandlerOptions>(options, logger, encoder)
197	{
198	    public const string SchemeName = "Test";
199	
200	    // ConcurrentDictionary is used instead of [ThreadStatic] because async request
201	    // processing can switch threads, making thread-local storage unreliable in tests.
202	    private static readonly ConcurrentDictionary<string, ClaimsPrincipal> _users = new();
203	
204	    public static string RegisterUser(ClaimsPrincipal user)
205	    {
206	        var token = Guid.NewGuid().ToString("N");
207	        _users[token] = user;
208	        return token;
209	    }
210	
211	    protected override Task<AuthenticateResult> HandleAuthenticateAsync()
212	    {
213	        if (!Request.Headers.TryGetValue("Authorization", out var authHeader))
214	            return Task.FromResult(AuthenticateResult.NoResult());
215	
216	        var headerValue = authHeader.ToString();
217	        var prefix = $"{SchemeName} ";
218	        if (!headerValue.StartsWith(prefix, StringComparison.Ordinal))
219	            return Task.FromResult(AuthenticateResult.NoResult());
220	
221	        var token = headerValue[prefix.Length..];
222	        if (!_users.TryGetValue(token, out var user))
223	            return Task.FromResult(AuthenticateResult.NoResult());
224	
225	        var ticket = new AuthenticationTicket(user, SchemeName);
226	        return Task.FromResult(AuthenticateResult.Success(ticket));
227	    }
228	}
